INSERT INTO instruments (instrument_id, authority_id, lg_id, kind, force, title, notes) VALUES ($q$LCC_PLANNING_SCHEME_2015$q$, $q$LCC$q$, $q$LOGAN$q$, 'PLANNING_SCHEME', 'STATUTORY_INSTRUMENT', $q$Logan Planning Scheme 2015$q$, $q$Council page (fetched 2026-10-08): 'The current version commenced on 1 July 2025 (Logan Planning Scheme 2015 V9.2).' PDF headers: 'Logan Planning Scheme 2015: 9.2 (with TLPI No. 1/2024) Effective Date: 01/07/2025', 'Status: Current', print date 30/06/2025. Council's public S3 document bucket contains no version later than V9.2 and no file modified after 2025 in the scheme or amendments folders (checked via S3 listing). TLPI No. 1/2024 (flood) 'commenced on 6 March 2025' and suspends some flood provisions. Replacement 'Logan Plan' draft was consulted 1 Sept - 31 Oct 2025; council page (Oct 2026) shows submission investigation in progress and no adoption/commencement date. Scheme does not apply to Yarrabilba and Greater Flagstone PDAs (EDQ). ePlan (logan.isoplan.com.au/eplan) returned HTTP 403 to automated fetch; official PDFs used instead.$q$);
