SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$QDC relationship: Part 1 s1.6(3) Table 1.6.1$q$, 'APPLICATION', $q$Alternative provisions to the QDC boundary clearance provisions | Dual occupancy and Dwelling house code, PO4/AO4, PO5/AO5, PO6/AO6 and PO7/AO7.1. | Section 33(2) BA.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%201%20About%20the%20planning%20scheme%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$QDC relationship: Part 1 s1.6(3) Table 1.6.1 #2$q$, 'APPLICATION', $q$Alternative provisions to the QDC site cover provisions | Dual occupancy and Dwelling house code: a. PO3/AO3 - maximum site cover b. PO7/AO7 - maximum gross floor area for class 10a buildings c. PO8/AO8 - maximum gross floor area for Dual occupancy (auxiliary unit) or secondary dwelling d. PO9/AO9 for maximum distance between dwellings for Dual occupancy (auxiliary unit) or secondary dwelling. | Section 33(2) BA.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%201%20About%20the%20planning%20scheme%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$QDC relationship: Part 1 s1.6(3) Table 1.6.1 #3$q$, 'APPLICATION', $q$Alternative provisions to the QDC on-site car parking provisions | Dual occupancy and Dwelling house code, PO12/AO12. | Section 33(2) BA.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%201%20About%20the%20planning%20scheme%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$QDC relationship: Part 1 s1.6 Editor's note$q$, 'APPLICATION', $q$specify alternative boundary clearances and site cover provisions for Class 1 and 10 structures under section 33 of the Building Act 1975.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%201%20About%20the%20planning%20scheme%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$QDC relationship: Part 1 s1.6 Editor's note #2$q$, 'APPLICATION', $q$Table 5.7.1 - Building work, which makes the following building work (other than minor building work) Accepted development (subject to requirements): extension of a Dual occupancy (auxiliary unit) or extension of a Dwelling house or a domestic building. The Accepted development requirements are the acceptable outcomes in section 9.3.2 - Dual occupancy and Dwelling house code. Building work that does not comply with one or more of the acceptable outcomes becomes code assessable development: section 5.3.3(2).$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%201%20About%20the%20planning%20scheme%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$QDC relationship: 9.3.2 Table 9.3.2.3.1 AO1$q$, 'APPLICATION', $q$AO1 A Dwelling house (and a secondary dwelling and any building or structure ancillary to a Dwelling house): a. that is on a lot that is less than 450m2 in size complies with the Acceptable Solutions specified in QDC MP 1.1 or b. that is on a lot that is 450m2 or greater in size complies with the Acceptable Solutions specified in QDC MP 1.2. Note - Where Table 9.3.2.3.1 AO3, AO4, AO5, AO6, AO7.1, AO8 or AO9 applies, AO3, AO4, AO5, AO6, AO7.1, AO8 or AO9 prevail over AO1 to the extent of any inconsistency.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$QDC relationship: Table 5.7.1 Editor's note$q$, 'APPLICATION', $q$For code assessable building work under this planning scheme, a development permit is required. A private certifier cannot receive or decide a building development application under the Building Act 1975 until the planning scheme development permit is in effect. See section 83 Building Act 1975 (General restrictions on granting building development approval).$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-7%20Tables%20of%20assessment%20-%20Building%20work%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Boundary clearance$q$, 'DEFINITION', $q$Boundary clearance means the distance between a building or structure on premises and the boundary of the premises, measured from the part of the building or structure that is closest to the boundary, other than a part that is - a. an architectural or ornamental attachment or b. a rainwater fitting. Examples 1 If the fascia of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between the outside of the fascia and the boundary. 2 If a point on the roof of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between that point on the roof and the boundary.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Side and rear boundary clearance$q$, 'DEFINITION', $q$For a building or structure on a lot, the shortest distance measured horizontally from the outermost projection of the building or structure to the vertical projection of the boundary of the lot but does not include a road boundary clearance.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Setback$q$, 'DEFINITION', $q$Setback, for a building or structure, means the shortest distance measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Outermost projection$q$, 'DEFINITION', $q$Outermost projection, of a building or structure, means the outermost part of the building or structure, other than a part that is - a. a retractable blind or b. a fixed screen or c. a rainwater fitting or d. an ornamental attachment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Site cover$q$, 'DEFINITION', $q$Site cover, of development, means the portion of the site, expressed as a percentage, that will be covered by a building or structure, measured to its outermost projection, after the development is carried out, other than a building or structure, or part of a building or structure, that is - a. in a landscaped or open space area, including, for example, a gazebo or shade structure or b. a basement that is completely below ground level and used for car parking or c. the eaves of a building or d. a sun shade.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Building height$q$, 'DEFINITION', $q$Building height, of a building, means a. the vertical distance, measured in metres, between the ground level of the building and the highest point on the roof of the building, other than a point that is part of an aerial, chimney, flagpole or load-bearing antenna or b. the number of storeys in the building above ground level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Ground level$q$, 'DEFINITION', $q$Ground level means a. the level of the natural ground or b. if the level of the natural ground has changed, the level as lawfully changed.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Domestic outbuilding$q$, 'DEFINITION', $q$Domestic outbuilding means a non-habitable class 10a building that is a. a shed, garage or carport and b. ancillary to a residential use carried out on the premises where the building is. Note - Sheds are considered to comprise barns, greenhouses, stables, workshops or the like.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Dwelling house$q$, 'DEFINITION', $q$Dwelling house means a residential use of premises involving - a. 1 dwelling for a single household and any domestic outbuildings associated with the dwelling or b. 1 dwelling for a single household, a secondary dwelling and any domestic outbuildings associated with either dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.1$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-1%20Use%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Corner lot$q$, 'DEFINITION', $q$A lot bounded by two or more roads where the roads intersect or join; and where the roads are open for public access and are for the driving or riding of motor vehicles. Note - A lot abutting a single street on a bend shall be considered a corner lot where the intersection of the centrelines at the bend in the street has an interior angle of less than 135 degrees.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Dual road lot$q$, 'DEFINITION', $q$A lot bounded by two or more roads where at least two of the roads are formed; and where the roads are open for public access and are for the driving or riding of motor vehicles.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Primary street frontage$q$, 'DEFINITION', $q$Where: a. a lot is vacant, the frontage most commonly addressed by other buildings in the street as the front of the lot or b. a lot is not vacant, the frontage to which the front of the existing building addresses the street.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Rear lot$q$, 'DEFINITION', $q$A lot that has access to a road by means only of: a. an access strip that forms part of the lot or b. an easement over an adjoining lot or c. common property as part of a community title scheme.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Storey$q$, 'DEFINITION', $q$Storey a. means a space within a building between 2 floor levels, or a floor level and a ceiling or roof, other than i. a space containing only a lift shaft, stairway or meter room or ii. a space containing only a bathroom, shower room, laundry, toilet or other sanitary compartment or iii. a space containing only a combination of the things stated in subparagraphs (i) or (ii) or iv. a basement with a ceiling that is not more than 1m above ground level and b. includes i. a mezzanine and ii. a roofed structured that is on, or part of, a rooftop, if the structure does not only accommodate building plant and equipment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Minor building work$q$, 'DEFINITION', $q$Minor building work means building work that increases the gross floor area of a building by no more than the lesser of the following - a. 50m2 b. an area equal to 5% of the gross floor area of the building.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Secondary dwelling$q$, 'DEFINITION', $q$Secondary dwelling means a dwelling, whether attached or detached, that is used in conjunction with, and subordinate to, a dwelling house on the same lot.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Development envelope area$q$, 'DEFINITION', $q$The area of a lot defined by metes and bounds within which all development including but not limited to a building, structure, private open space, car parking area, storage, on-site wastewater treatment and associated clearing of vegetation is confined other than a boundary fence. The term does not include an accessway from a road to the development envelope area.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Residential zone category$q$, 'DEFINITION', $q$The following zones: Low density residential zone; Low-medium density residential zone; Medium density residential zone.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Structure$q$, 'DEFINITION', $q$Includes a wall or fence and anything fixed to or projecting from a building, wall, fence or other structure. Note - definition from the Building Act 1975.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 (verified against rendered page 14)$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$def Frontage / Secondary frontage / Wall height$q$, 'DEFINITION', $q$NOT DEFINED - no 'Frontage', 'Secondary frontage' or 'Wall height' entry appears in the SC1.2 index of administrative definitions (index text checked). 'Primary street frontage' and 'Corner lot' are defined (above).$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 index$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, NULL, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.7.1 Building work - extension of Dwelling house / Dual occupancy (auxiliary unit) (incl. ancillary class 10) / All zones$q$, 'LEVEL_OF_ASSESSMENT', $q$All zones where for a Dual occupancy (auxiliary unit) or Dwelling house | Accepted development (subject to requirements) | Development for the extension of a Dual occupancy (auxiliary unit) or Dwelling house. Editor's Note - A Dwelling house includes ancillary class 10 buildings or structures where subordinate to the primary use. | 9.3.2 Dual occupancy and Dwelling house code. ... Accepted development (not subject to requirements) Minor building work and any other building work not listed in this table.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-7%20Tables%20of%20assessment%20-%20Building%20work%20(LPS%20v9_2).pdf$q$, $q$Level: Accepted development (subject to requirements). Conditions: Not minor building work (minor building work and building work not listed = accepted, not subject to requirements). Non-compliance with an AO -> code assessable (s5.3.3(2)).$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.10.10.1 Material change of use - Dwelling house; class 10 building or structure for a Dwelling house / Residential area on Residential overlay map OM-10.00 (EC, EMC, LDR all precincts, LMD$q$, 'LEVEL_OF_ASSESSMENT', $q$Material change of use | Accepted development (subject to requirements) If in a residential area and - a. for a Dwelling house or b. for a class 10 building or structure for a Dwelling house. | 9.3.2 Dual occupancy and Dwelling house code | Accepted development (subject to requirements) If in a residential area and for a class 10 building or structure for a residential activity other than for a Dwelling house. | The zone code for the zone area. The local plan code for the local plan area.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-10%20Tables%20of%20assessment%20-%20Overlays%20(LPS%20v9_2%20with%20TLPI%201_2024).pdf$q$, $q$Level: Accepted development (subject to requirements). Conditions: In a 'residential area'; requirement = 9.3.2 Dual occupancy and Dwelling house code. Overlay category overrides zone (s5.3.2(8)).$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.5.5.1 (same note in Tables 5.5.3.1, 5.5.7.1, 5.5.8.1, 5.5.12.1, 5.5.13.1, 5.9.6.1, 5.9.7.1) Material change of use - Dwelling house / Low density residential zone (also EC, RR, LMDR, Rural$q$, 'LEVEL_OF_ASSESSMENT', $q$Accepted development (not subject to requirements) Editor's note - A Dwelling house becomes Accepted development (subject to requirements) where mapped in a residential area on Residential overlay map OM-10.00. The relevant assessment benchmark in section 5.10.10 is the 9.3.2 Dual occupancy and Dwelling house code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-5%20Tables%20of%20assessment%20-%20Material%20change%20of%20use%20(LPS%20v9_2).pdf$q$, $q$Level: Accepted development (not subject to requirements) in the zone table, elevated by Residential overlay. Conditions: Zone table editor's note points to Residential overlay.$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA SC1.2 Administrative definitions 'Residential area' definition (for Part 5) / n/a$q$, 'LEVEL_OF_ASSESSMENT', $q$For the purposes of Part 5 - Tables of assessment Residential area means land, other than a road reserve, within the: Emerging community zone; Environmental management and conservation zone (all precincts); Low density residential zone (all precincts); Low-medium density residential zone (all precincts); Medium density residential zone (all precincts); Rural zone (all precincts); Rural residential zone (all precincts); Loganholme local plan ... Loganlea local plan ...$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%201-2%20Administrative%20definitions%20(LPS%20v9_2).pdf$q$, $q$Level: definition. Conditions: Determines where Table 5.10.10.1 applies.$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.5.3.1 all uses row Any use with new building work exceeding height (impact trigger) / Emerging community zone$q$, 'LEVEL_OF_ASSESSMENT', $q$b. the building height in the Dual occupancy and Dwelling house code, if Dual occupancy (auxiliary unit) or Dwelling house being - i. 8.5 metres on a site with a slope less than 15 percent or ii. 10 metres on a site with a slope 15 percent or more.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-5%20Tables%20of%20assessment%20-%20Material%20change%20of%20use%20(LPS%20v9_2).pdf$q$, $q$Level: Impact assessment. Conditions: Dwelling house: building height exceeding 8.5 m (slope < 15%) or 10 m (slope >= 15%)$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.5.5.1 all uses row Any use with new building work exceeding height (impact trigger) / Low density residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$If not accepted development (not subject to requirements) and new building work results in a building height (other than if Animal husbandry, Animal keeping, Dwelling house, Park or Sales office), exceeding - a. 8.5 metres on a site with a slope less than 15 percent or b. 10 metres on a site with a slope of 15 percent or more.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-5%20Tables%20of%20assessment%20-%20Material%20change%20of%20use%20(LPS%20v9_2).pdf$q$, $q$Level: Impact assessment (Dwelling house excluded). Conditions: Excludes Animal husbandry, Animal keeping, Dwelling house, Park, Sales office$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.10.7.1 Building work (any) in heritage area / All zones$q$, 'LEVEL_OF_ASSESSMENT', $q$Code assessment If - a. not carried out by the local government b. not on land owned by the local government or of which the local government is the trustee. ... Editor's note - The local government is the assessment manager for building work made assessable by this table.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-10%20Tables%20of%20assessment%20-%20Overlays%20(LPS%20v9_2%20with%20TLPI%201_2024).pdf$q$, $q$Level: Code assessment. Conditions: Heritage overlay OM-07.00; not carried out by / on land of local government$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.10.5.1 (TLPI 1/2024 version) Building work associated with Dwelling house in flood overlay / All zones$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work associated with a Dual occupancy (auxiliary unit) or Dwelling house | No change If - a. located outside of a High flow area on Flood hazard overlay map OM-05.02 b. building work: i. does not exceed 25m2 ii. does not involve enclosing an undercroft in a High flood risk area on Flood hazard overlay map OM-05.04.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-10%20Tables%20of%20assessment%20-%20Overlays%20(LPS%20v9_2%20with%20TLPI%201_2024).pdf$q$, $q$Level: No change (requirements from 9.3.2 / 8.2.5 added). Conditions: Outside High flow area and building work <= 25m2 and no undercroft enclosure in High flood risk area -> 9.3.2 + 8.2.5 AO8.1/AO8.2 + 9.3.2 AO38; otherwise 9.3.2 / 8.2.5 Part E where in High/Moderate flood risk or Flood investigation area$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA Table 5.10.3.1 (Bushfire hazard overlay) Building work / MCU for Dwelling house in bushfire, landslide, regional infrastructure overlays / All zones$q$, 'LEVEL_OF_ASSESSMENT', $q$No change If - a. in an approved development envelope area or b. development is undertaken in accordance with an existing bushfire management plan approved by Council or c. for a Dual occupancy (auxiliary unit) or d. for a Dwelling house. Editor's Note - A Dwelling house includes ancillary class 10 buildings or structures where subordinate to the primary use. | Not applicable$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-10%20Tables%20of%20assessment%20-%20Overlays%20(LPS%20v9_2%20with%20TLPI%201_2024).pdf$q$, $q$Level: No change; overlay code Not applicable for Dwelling house. Conditions: Overlay requirements for Dwelling house are folded into 9.3.2$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$LOA s5.3.3(4)(b) How code assessment is scoped after failing an AO / All$q$, 'LEVEL_OF_ASSESSMENT', $q$that occurs as a result of development becoming code assessable pursuant to section 5.3.3(2), must: i. be assessed against the assessment benchmarks for the development application, limited to the subject matter of the required acceptable outcomes that were not complied with or were not capable of being complied with under section 5.3.3(2) ii. comply with all required acceptable outcomes identified in section 5.3.3(1), other than those mentioned in section 5.3.3(2)$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%205-3%20Tables%20of%20assessment%20-%20Categories%20(v9_2).pdf$q$, $q$Level: Code assessment (limited). Conditions: s5.3.3(4)(b)$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$overlay Flood hazard overlay (with TLPI No. 1/2024) 9.3.2 AO31.1, AO33, AO34, Table 9.3.2.3.3$q$, 'OTHER', $q$AO34 A domestic outbuilding is located outside a High flood risk area identified on Flood hazard overlay map OM-05.04.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$9.3.2 Dual occupancy and Dwelling house code (overlay provisions); 8.2.5 Flood hazard overlay code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$Prohibits buildings/structures (other than fences) in High flow area; domestic outbuildings must be outside High flood risk area; minimum floor levels for outbuildings/carports (Table 9.3.2.3.3).$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$overlay Landslide hazard and steep slope area overlay 9.3.2 AO27$q$, 'OTHER', $q$c. development is designed to ensure that the undercroft of the building or structure has: i. skirting or landscape screening to the full height of the undercroft ii. a maximum height at the perimeter of the building or structure of 3 metres above ground level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$Undercroft perimeter height max 3 m above ground level and screened; cut/fill max 40 m3; geotechnical report.$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$overlay Heritage overlay 8.2.7 AO3.1; PSP4 part 4$q$, 'OTHER', $q$locating the swimming pool at the side or rear, rather than in front of the house.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$8.2.7 Heritage overlay code + PSP4 Heritage$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Sc%206-2%20PSP4%20Heritage%20(LPS%20v9_2).pdf$q$, $q$Building work code assessable; carports/garages not to dominate frontage or be at rear; pools/decks at side or rear rather than in front (qualitative, no numbers).$q$, NULL);
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$overlay Biodiversity areas / Waterway corridors / Regional infrastructure / Water resource catchments overlays 9.3.2 AO20-AO22, AO28-AO30$q$, 'OTHER', $q$AO30 A Dual occupancy (auxiliary unit) or Dwelling house that is not within a development envelope area approved by a development approval is located outside the mapped area identified on Waterway corridors and wetlands overlay map OM-14.00.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$Locational requirements (e.g. outside mapped area unless within approved development envelope; koala corridor clearing max 500m2) rather than numeric setbacks.$q$, NULL);

SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 PO1/AO1$q$, 'ACCEPTABLE_OUTCOME', $q$AO1 A Dwelling house (and a secondary dwelling and any building or structure ancillary to a Dwelling house): a. that is on a lot that is less than 450m2 in size complies with the Acceptable Solutions specified in QDC MP 1.1 or b. that is on a lot that is 450m2 or greater in size complies with the Acceptable Solutions specified in QDC MP 1.2. Note - Where Table 9.3.2.3.1 AO3, AO4, AO5, AO6, AO7.1, AO8 or AO9 applies, AO3, AO4, AO5, AO6, AO7.1, AO8 or AO9 prevail over AO1 to the extent of any inconsistency. Note - For the purposes of the QDC and this acceptable outcome, the nominated road frontage for the road boundary clearance of a corner lot is the narrower frontage. Note - References to QDC MP 1.1 and 1.2 for the purposes of AO1 are to be applied as if these provisions applied to a secondary dwelling. Editor's note - A building or structure ancillary to a Dwelling house includes a class 10a building, being a non-habitable building such as a private garage, carport, shed or the like.$q$, 'VERIFIED_VERBATIM', $q$Page 2 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$Defers to QDC MP1.1/MP1.2 measurement rules (now QHC Parts 1.1/1.2 from 1 Sept 2026 - see notes).$q$, $q$dh_ao1_qdc_mp11_mp12_default$q$);
SELECT define_rule($q${"rule_id": "LCC.dh_ao1_qdc_mp11_mp12_default", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "OTHER", "title": "Table 9.3.2.3.1 PO1/AO1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "AO1 A Dwelling house (and a secondary dwelling and any building or structure ancillary to a Dwelling house): a. that is on a lot that is less than 450m2 in size complies with the Acceptable Solutions specified in QDC MP 1.1 or b. that is on a lot that is 450m2 or greater in size complies with the Acceptable Solutions specified in QDC MP 1.2. Note - Where Table 9.3.2.3.1 AO3, AO4, AO5, AO6, AO7.1, AO8 or AO9 applies, AO3, AO4, AO5, AO6, AO7.1, AO8 or AO9 prevail over AO1 to the extent of any inconsistency. Note - For the purposes of the QDC and this acceptable outcome, the nominated road frontage for the road boundary clearance of a corner lot is the narrower frontage. Note - References to QDC MP 1.1 and 1.2 for the purposes of AO1 are to be applied as if these provisions applied to a secondary dwelling. Editor's note - A building or structure ancillary to a Dwelling house includes a class 10a building, being a non-habitable building such as a private garage, carport, shed or the like.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}], "subjects": ["ANY"], "sources": [{"key": "dh_ao1_qdc_mp11_mp12_default", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"qdc_part_applicable\", \"operator\": \"conditional\", \"value\": null, \"unit\": null, \"conditions\": [\"lot area < 450 m2 -> QDC MP 1.1 Acceptable Solutions\", \"lot area >= 450 m2 -> QDC MP 1.2 Acceptable Solutions\"], \"exceptions\": [\"AO3, AO4, AO5, AO6, AO7.1, AO8, AO9 prevail over AO1 to the extent of inconsistency\"], \"formula_text\": null}\nLot conditions (not encoded): lot < 450 m2 -> QDC MP 1.1; lot >= 450 m2 -> QDC MP 1.2\nStructure scope 'Dwelling house, secondary dwelling and any building or structure ancillary to a Dwelling house (incl. class 10a garage, carport, shed)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO\nResearcher notes: AO1 itself is not listed in Table 1.6.1 as an alternative provision; it simply incorporates the QDC acceptable solutions as accepted-development requirements under the planning scheme. Scheme v9.2 (1 July 2025) still refers to 'QDC MP 1.1' and 'QDC MP 1.2'; no 2026 amendment referring to the Queensland Housing Code was found. How these references operate after the QHC replaced MP1.1/MP1.2 on 1 Sept 2026 needs legal review (transitional/reference provisions in the Building Act/QDC). The 450m2 split matches QHC Chapter 1/Chapter 2."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.dh_ao1_qdc_mp11_mp12_default@2025-07-01$q$;
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 AO1, Note$q$, 'OTHER', $q$Note - For the purposes of the QDC and this acceptable outcome, the nominated road frontage for the road boundary clearance of a corner lot is the narrower frontage.$q$, 'VERIFIED_VERBATIM', $q$Page 2 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$'Corner lot' (SC1.2): 'A lot bounded by two or more roads where the roads intersect or join; and where the roads are open for public access and are for the driving or riding of motor vehicles.' Note - bend in a single street with interior angle < 135 degrees counts as corner lot.$q$, $q$dh_ao1_corner_lot_nominated_frontage$q$);
SELECT define_rule($q${"rule_id": "LCC.dh_ao1_corner_lot_nominated_frontage", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.SECONDARY_ROAD", "title": "Table 9.3.2.3.1 AO1, Note", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_SECONDARY_FRONTAGE", "operator": "=", "value": {"op": "unencoded", "text": "Note - For the purposes of the QDC and this acceptable outcome, the nominated road frontage for the road boundary clearance of a corner lot is the narrower frontage.", "extracted_value": "narrower frontage", "extracted_operator": "="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_ao1_corner_lot_nominated_frontage", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"nominated_road_frontage_corner_lot\", \"operator\": \"=\", \"value\": \"narrower frontage\", \"unit\": null, \"conditions\": [\"corner lot\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): corner lot\nStructure scope 'Dwelling house and ancillary buildings/structures (incl. class 10a)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: Appears as a note to AO1 (and AO2). AO1 is not in Table 1.6.1, so its status as an 'alternative provision' is unclear; it nonetheless determines which frontage is the primary (QDC 'nominated') road frontage for QDC/QHC road setbacks."}$q$::jsonb);
