SELECT define_rule($q${"rule_id": "LCC.dh_ao4a_carport_to_front_boundary", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "GARAGE.FRONTAGE", "title": "Table 9.3.2.3.1 PO4/AO4(a)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "If all conditions met, carport may be built to the front (road) boundary (0 m).", "extracted_value": 0, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}], "subjects": ["CLASS_10A"], "sources": [{"key": "dh_ao4a_carport_to_front_boundary", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"carport_min_road_boundary_clearance\", \"operator\": \"conditional\", \"value\": 0, \"unit\": \"m\", \"conditions\": [\"carport max dimensions 6 m x 6 m\", \"carport max height 3.5 m\", \"carport entirely unenclosed except where rear attaches to a structure\"], \"exceptions\": [], \"formula_text\": \"If all conditions met, carport may be built to the front (road) boundary (0 m).\"}\nStructure scope 'carport' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Basis: Part 1 s1.6(3) Table 1.6.1: 'Alternative provisions to the QDC boundary clearance provisions | Dual occupancy and Dwelling house code, PO4/AO4, PO5/AO5, PO6/AO6 and PO7/AO7.1. | Section 33(2) BA.' Applies in all zones, including LDR Suburban/Small lot where no other road clearance is set by AO4."}$q$::jsonb);
