SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 PO4/AO4(b)$q$, 'ACCEPTABLE_OUTCOME', $q$AO4 A Dual occupancy or Dwelling house: ... b. has a minimum road boundary clearance of 4 metres in the Low-medium density residential zone$q$, 'VERIFIED_VERBATIM', $q$Page 3 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$'Boundary clearance' (SC1.2) is measured 'from the part of the building or structure that is closest to the boundary, other than a part that is - a. an architectural or ornamental attachment or b. a rainwater fitting' (e.g. outside of fascia, or nearest point of roof). Note this differs from the scheme's 'Setback' definition (measured from the 'outermost projection').$q$, $q$dh_ao4b_road_clearance_lmdr_4m$q$);
