SELECT define_rule($q${"rule_id": "LCC.dh_ao4_no_value_ldr_suburban_smalllot_village", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.FRONTAGE", "title": "Table 9.3.2.3.1 AO4 (absence)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "Fall back to AO1 -> QDC MP1.1/MP1.2 (now QHC) road setback, plus AO4(a) carport concession.", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "UNVERIFIED", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/LARGE_SUBURBAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/SMALL_LOT"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/SUBURBAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/VILLAGE"}, {"level": "ZONE", "zone": "LCC:MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_ao4_no_value_ldr_suburban_smalllot_village", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_road_boundary_clearance\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": \"Fall back to AO1 -> QDC MP1.1/MP1.2 (now QHC) road setback, plus AO4(a) carport concession.\"}\nStructure scope 'Dwelling house and class 10a' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: DERIVED INFERENCE (not a quoted provision): drawn from the verified full text of 9.3.2 AO4/AO5, which simply do not list these zones/precincts. Derived by reading AO4 in full (not a quoted rule). The LDR zone code Table 6.2.5.3.3 does have road clearances for these precincts (4 m Small lot, 6 m Suburban/Large suburban/Village) but is not a nominated requirement for Dwelling houses under Table 5.10.10.1 and is not an alternative provision in Table 1.6.1."}$q$::jsonb);
