SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 PO5/AO5(a)$q$, 'ACCEPTABLE_OUTCOME', $q$AO5 A Dual occupancy or Dwelling house has the following minimum side and rear boundary clearances: a. 3 metres in the Rural residential zone, the Emerging community zone and the following precincts in the Low density residential zone: i. Acreage ii. Small acreage precinct or ... Note - AO5 does not apply to a domestic outbuilding, being a shed or detached garage, that complies with Link AO7.1(b).$q$, 'VERIFIED_VERBATIM', $q$Page 3 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$'Side and rear boundary clearance' (SC1.2): 'the shortest distance measured horizontally from the outermost projection of the building or structure to the vertical projection of the boundary of the lot but does not include a road boundary clearance.' General 'Boundary clearance' definition (closest part, excluding architectural/ornamental attachments and rainwater fittings) also exists - manual review which governs.$q$, $q$dh_ao5a_side_rear_3m$q$);
SELECT define_rule($q${"rule_id": "LCC.dh_ao5a_side_rear_3m", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.SIDE", "title": "Table 9.3.2.3.1 PO5/AO5(a)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 3, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "ZONE", "zone": "LCC:RURAL_RESIDENTIAL"}, {"level": "ZONE", "zone": "LCC:EMERGING_COMMUNITY"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/ACREAGE"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/SMALL_ACREAGE"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_ao5a_side_rear_3m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_and_rear_boundary_clearance\", \"operator\": \">=\", \"value\": 3, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [\"domestic outbuilding (shed or detached garage) complying with AO7.1(b) - see Table 9.3.2.3.2\"], \"formula_text\": null}\nStructure scope 'Dual occupancy or Dwelling house (incl. ancillary class 10a, except domestic outbuilding complying with AO7.1(b))' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Basis: Part 1 s1.6(3) Table 1.6.1: 'Alternative provisions to the QDC boundary clearance provisions | Dual occupancy and Dwelling house code, PO4/AO4, PO5/AO5, PO6/AO6 and PO7/AO7.1. | Section 33(2) BA.' Applies to both side and rear boundaries. No height-variable formula in 9.3.2."}$q$::jsonb);
