SELECT define_rule($q${"rule_id": "LCC.dh_ao5_no_value_urban_zones", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.SIDE", "title": "Table 9.3.2.3.1 AO5 (absence)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "OTHER", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "Fall back to AO1 -> QDC MP1.1/MP1.2 (now QHC) side/rear clearances and built-to-boundary rules.", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "UNVERIFIED", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/LARGE_SUBURBAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/SMALL_LOT"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/SUBURBAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/VILLAGE"}, {"level": "ZONE", "zone": "LCC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}, {"level": "ZONE", "zone": "LCC:MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_ao5_no_value_urban_zones", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_and_rear_boundary_clearance\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": \"Fall back to AO1 -> QDC MP1.1/MP1.2 (now QHC) side/rear clearances and built-to-boundary rules.\"}\nStructure scope 'Dwelling house and class 10a' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: DERIVED INFERENCE (not a quoted provision): drawn from the verified full text of 9.3.2 AO4/AO5, which simply do not list these zones/precincts. Derived reading. For urban residential lots, the QDC/QHC side/rear and built-to-boundary provisions govern houses and Class 10a, except large outbuildings (>150m2) which must meet AO7.1(b) - but Table 9.3.2.3.2 lists no clearance for urban LDR precincts, LMDR or MDR (see open questions)."}$q$::jsonb);
