SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$6.2.8.3 Table (Design), Boundary clearance, PO4/AO4$q$, 'ACCEPTABLE_OUTCOME', $q$AO4 Development, other than an existing lawful building, provides a road boundary clearance: a. a minimum of six metres; or b. where the building or structure aligns with the building setback of one or more adjoining buildings.$q$, 'VERIFIED_VERBATIM', $q$Part 6-2-8 Zone code - Medium density residential (LPS v9_2).pdf, p.3 (section 6.2.8.3 Design)$q$, NULL, $q$6.2.8 Medium density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-8%20Zone%20code%20-%20Medium%20density%20residential%20(LPS%20v9_2).pdf$q$, NULL, $q$mdr_ao4_road_boundary_clearance$q$);
SELECT define_rule($q${"rule_id": "LCC.mdr_ao4_road_boundary_clearance", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.FRONTAGE", "title": "6.2.8.3 Table (Design), Boundary clearance, PO4/AO4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "AO4 Development, other than an existing lawful building, provides a road boundary clearance: a. a minimum of six metres; or b. where the building or structure aligns with the building setback of one or more adjoining buildings.", "extracted_value": 6, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "ZONE", "zone": "LCC:MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mdr_ao4_road_boundary_clearance", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"road_boundary_clearance\", \"operator\": \"conditional\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"minimum 6 m, or aligns with an adjoining building's setback\"], \"exceptions\": [\"existing lawful building\"], \"formula_text\": null}\nStructure scope 'development in the Medium density residential zone other than a Dwelling house or a Class 10 structure for a Dwelling house' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - not nominated for a Dwelling house or its Class 10 structures; see notes.\nResearcher notes: Found while checking a user-supplied screenshot of this exact table (23 Oct 2026). Confirmed verbatim against the live PDF (Part 6-2-8, pdftotext extraction). Table 5.10.10.1 (verified verbatim, in levels_of_assessment) lists the Medium density residential zone as a 'Residential area' on the Residential overlay map OM-10.00, and nominates ONLY the 9.3.2 Dual occupancy and Dwelling house code for 'a Dwelling house' or 'a class 10 building or structure for a Dwelling house'; the zone code (6.2.8, this provision) is nominated only for 'a class 10 building or structure for a residential activity other than for a Dwelling house' (s5.3.2(8): overlay category overrides zone). So this PO4/AO4/PO5/AO5 table applies to the zone's own multiple-dwelling/apartment development, not to a dwelling house or its Class 10 outbuildings. For a dwelling house / its Class 10 in the MDR zone, 9.3.2 AO4 and AO5 both give no numeric value for MDR (see dh_ao4_no_value_ldr_suburban_smalllot_village, dh_ao5_no_value_urban_zones), so the QDC/QHC governs. This confirms, rather than changes, that existing conclusion."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.mdr_ao4_road_boundary_clearance@2025-07-01$q$;
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$6.2.8.3 Table (Design), Boundary clearance, PO5/AO5$q$, 'ACCEPTABLE_OUTCOME', $q$AO5 Development, other than an existing lawful building provides a minimum side and rear boundary clearance of: a. three metres in the Medium rise precinct; b. six metres in the High rise precinct.$q$, 'VERIFIED_VERBATIM', $q$Part 6-2-8 Zone code - Medium density residential (LPS v9_2).pdf, p.3 (section 6.2.8.3 Design)$q$, NULL, $q$6.2.8 Medium density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-8%20Zone%20code%20-%20Medium%20density%20residential%20(LPS%20v9_2).pdf$q$, $q$Applies to side AND rear boundaries.$q$, $q$mdr_ao5_side_rear_boundary_clearance$q$);
SELECT define_rule($q${"rule_id": "LCC.mdr_ao5_side_rear_boundary_clearance", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.SIDE", "title": "6.2.8.3 Table (Design), Boundary clearance, PO5/AO5", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "3 m (Medium rise precinct) / 6 m (High rise precinct)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "ZONE", "zone": "LCC:MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mdr_ao5_side_rear_boundary_clearance", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side_rear_boundary_clearance\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"3 m in the Medium rise precinct\", \"6 m in the High rise precinct\"], \"exceptions\": [\"existing lawful building\"], \"formula_text\": \"3 m (Medium rise precinct) / 6 m (High rise precinct)\"}\nStructure scope 'development in the Medium density residential zone other than a Dwelling house or a Class 10 structure for a Dwelling house' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - not nominated for a Dwelling house or its Class 10 structures; see notes.\nResearcher notes: Found while checking a user-supplied screenshot of this exact table (23 Oct 2026). Confirmed verbatim against the live PDF (Part 6-2-8, pdftotext extraction). Table 5.10.10.1 (verified verbatim, in levels_of_assessment) lists the Medium density residential zone as a 'Residential area' on the Residential overlay map OM-10.00, and nominates ONLY the 9.3.2 Dual occupancy and Dwelling house code for 'a Dwelling house' or 'a class 10 building or structure for a Dwelling house'; the zone code (6.2.8, this provision) is nominated only for 'a class 10 building or structure for a residential activity other than for a Dwelling house' (s5.3.2(8): overlay category overrides zone). So this PO4/AO4/PO5/AO5 table applies to the zone's own multiple-dwelling/apartment development, not to a dwelling house or its Class 10 outbuildings. For a dwelling house / its Class 10 in the MDR zone, 9.3.2 AO4 and AO5 both give no numeric value for MDR (see dh_ao4_no_value_ldr_suburban_smalllot_village, dh_ao5_no_value_urban_zones), so the QDC/QHC governs. This confirms, rather than changes, that existing conclusion."}$q$::jsonb);
