SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 PO6/AO6$q$, 'ACCEPTABLE_OUTCOME', $q$AO6 Where located on a rear lot and sharing access, via an access strip, easement or common property, with four or more rear lots, the garage of a Dual occupancy or Dwelling house has a minimum setback to the accessway of 4.9 metres.$q$, 'VERIFIED_VERBATIM', $q$Page 3 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$'Setback' (SC1.2): shortest horizontal distance from the outermost projection to the vertical projection of the boundary. 'Rear lot' (SC1.2): 'A lot that has access to a road by means only of: a. an access strip that forms part of the lot or b. an easement over an adjoining lot or c. common property as part of a community title scheme.'$q$, $q$dh_ao6_rear_lot_garage_accessway_4_9m$q$);
SELECT define_rule($q${"rule_id": "LCC.dh_ao6_rear_lot_garage_accessway_4_9m", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "GARAGE.FRONTAGE", "title": "Table 9.3.2.3.1 PO6/AO6", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": 4.9, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "dh_ao6_rear_lot_garage_accessway_4_9m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_garage_setback_to_accessway\", \"operator\": \">=\", \"value\": 4.9, \"unit\": \"m\", \"conditions\": [\"rear lot\", \"shares access with four or more rear lots\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): rear lot sharing access via access strip, easement or common property with four or more rear lots\nStructure scope 'garage of a Dual occupancy or Dwelling house' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Basis: Part 1 s1.6(3) Table 1.6.1: 'Alternative provisions to the QDC boundary clearance provisions | Dual occupancy and Dwelling house code, PO4/AO4, PO5/AO5, PO6/AO6 and PO7/AO7.1. | Section 33(2) BA.'"}$q$::jsonb);
