SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 PO7/AO7.1(a)$q$, 'ACCEPTABLE_OUTCOME', $q$AO7.1 A single domestic outbuilding, being a shed or detached garage, or multiple domestic outbuildings, being sheds or detached garages: a. has a total maximum floor area of 150m2 or b. where the floor area exceeds 150m2: ... Editor's note - The total maximum floor area is a cumulative total that applies across all domestic outbuildings on a premises.$q$, 'VERIFIED_VERBATIM', $q$Pages 3-4 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$'Floor area' not separately defined here; GFA definition measures from outside of external walls. Carports are domestic outbuildings by definition but AO7.1 is expressed for sheds/detached garages only.$q$, $q$dh_ao7_1a_outbuilding_total_floor_area_150$q$);
SELECT define_rule($q${"rule_id": "LCC.dh_ao7_1a_outbuilding_total_floor_area_150", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "OUTBUILDING.SIZE", "title": "Table 9.3.2.3.1 PO7/AO7.1(a)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": 150, "unit": "m2", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}], "subjects": ["CLASS_10A"], "sources": [{"key": "dh_ao7_1a_outbuilding_total_floor_area_150", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_total_outbuilding_floor_area\", \"operator\": \"<=\", \"value\": 150, \"unit\": \"m2\", \"conditions\": [\"applies to sheds and detached garages; cumulative across all domestic outbuildings on premises\"], \"exceptions\": [\"may exceed 150 m2 up to 300 m2 if AO7.1(b) met\"], \"formula_text\": null}\nStructure scope 'domestic outbuilding being a shed or detached garage (single or multiple, cumulative)' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Basis: Table 1.6.1 lists PO7/AO7.1 as alternative boundary clearance provisions and 'PO7/AO7 - maximum gross floor area for class 10a buildings' as alternative site cover provisions. Whether the cumulative total includes carports/attached garages needs review (text says 'being sheds or detached garages'). Council web page summary (search snippet) repeats this 150m2 rule."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.dh_ao7_1a_outbuilding_total_floor_area_150@2025-07-01$q$;
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 PO7/AO7.1(b)(ii)$q$, 'ACCEPTABLE_OUTCOME', $q$b. where the floor area exceeds 150m2: i. provides minimum side and rear boundary clearances in accordance with Link Table 9.3.2.3.2 - Minimum side and rear boundary clearances for large domestic outbuildings ii. has a maximum building height of 5.5 metres iii. has a total maximum floor area of 300m2.$q$, 'VERIFIED_VERBATIM', $q$Pages 3-4 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, $q$'Building height' (SC1.2): vertical distance between ground level and highest point of the roof (excluding aerial, chimney, flagpole, load-bearing antenna), or number of storeys above ground level.$q$, $q$dh_ao7_1b_large_outbuilding_height_5_5m$q$);
