SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 PO27/AO27(c)$q$, 'ACCEPTABLE_OUTCOME', $q$AO27 Where a Dual occupancy (auxiliary unit) or Dwelling house is proposed to be located in a Steep slope area identified on Landslide hazard and steep slope area overlay map OM-08.00 and the gradient is equal to or greater than 12 percent or located in a Historical landslide area identified on Landslide hazard and steep slope area overlay map OM-08.01: a. development is carried out in accordance with a site specific geotechnical report ... b. development does not involve cut and fill of more than 40m3 c. development is designed to ensure that the undercroft of the building or structure has: i. skirting or landscape screening to the full height of the undercroft ii. a maximum height at the perimeter of the building or structure of 3 metres above ground level.$q$, 'VERIFIED_VERBATIM', $q$Page 6 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, NULL, $q$dh_ao27_landslide_undercroft_height$q$);
SELECT define_rule($q${"rule_id": "LCC.dh_ao27_landslide_undercroft_height", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "HEIGHT.BUILDING", "title": "Table 9.3.2.3.1 PO27/AO27(c)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 3, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "OVERLAY", "overlay": "LCC:OV:LANDSLIDE_HAZARD_AND_STEEP_SLOPE_AREA_OVERLAY_OM_08_00_OM_08_01"}], "subjects": ["CLASS_1"], "sources": [{"key": "dh_ao27_landslide_undercroft_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_undercroft_perimeter_height\", \"operator\": \"<=\", \"value\": 3, \"unit\": \"m\", \"conditions\": [\"in steep slope area >= 12% gradient or historical landslide area\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): Steep slope area with gradient >= 12% or Historical landslide area\nStructure scope 'Dual occupancy (auxiliary unit) or Dwelling house (building or structure)' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Also cut and fill max 40m3. Note Table 5.10.8.1 says building work for a Dwelling house is 'No change' / 'Not applicable' for the overlay code itself; the overlay requirements are folded into 9.3.2."}$q$::jsonb);
