SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 9.3.2.3.1 AO31.1, AO33, AO34$q$, 'ACCEPTABLE_OUTCOME', $q$AO31.1 Buildings and structures, other than fences, are located outside of a High flow area identified on Flood hazard overlay map OM-05.02. ... AO33 Development, other than a domestic outbuilding, is located outside a High flood risk area identified on Flood hazard overlay map OM-05.04. ... AO34 A domestic outbuilding is located outside a High flood risk area identified on Flood hazard overlay map OM-05.04.$q$, 'VERIFIED_VERBATIM', $q$Pages 7-8 of 10$q$, NULL, $q$9.3.2 Dual occupancy and Dwelling house code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%209-3-2%20Dev%20code%20-%20Dual%20occ%20%26%20Dwelling%20house%20(LPS%20v9_2).pdf$q$, NULL, $q$dh_ao31_33_34_flood_location$q$);
SELECT define_rule($q${"rule_id": "LCC.dh_ao31_33_34_flood_location", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "OTHER", "title": "Table 9.3.2.3.1 AO31.1, AO33, AO34", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "AO31.1 Buildings and structures, other than fences, are located outside of a High flow area identified on Flood hazard overlay map OM-05.02. ... AO33 Development, other than a domestic outbuilding, is located outside a High flood risk area identified on Flood hazard overlay map OM-05.04. ... AO34 A domestic outbuilding is located outside a High flood risk area identified on Flood hazard overlay map OM-05.04.", "extracted_value": true, "extracted_operator": "="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "OVERLAY", "overlay": "LCC:OV:FLOOD_HAZARD_OVERLAY_OM_05_02_HIGH_FLOW_AREA_OM_05_04_HIGH_FLOOD_RISK_AREA_AS_AMENDED_BY_TLPI_NO_1_2"}], "subjects": ["ANY"], "sources": [{"key": "dh_ao31_33_34_flood_location", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"location_outside_flood_area\", \"operator\": \"=\", \"value\": true, \"unit\": null, \"conditions\": [\"applies where building work > 25m2 in High/Moderate flood risk or Flood investigation area, or any building work in High flow area or enclosing undercroft in High flood risk area (per heading above PO31)\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'buildings and structures other than fences; domestic outbuildings' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Table 9.3.2.3.3 also sets minimum floor levels for domestic outbuildings (carport: roof structure above DFE or RPEQ certification). Older flood provisions PO24-PO26 are shown as suspended by TLPI No. 1/2024."}$q$::jsonb);
