SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 6.2.5.3.1 PO2/AO2$q$, 'ACCEPTABLE_OUTCOME', $q$AO2 A building on a slope of: a. less than 15 percent has a maximum building height of 8.5 metres or b. 15 percent or more has a maximum building height of 10 metres.$q$, 'VERIFIED_VERBATIM', $q$Page 2 of 6$q$, NULL, $q$6.2.5 Low density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-5%20Zone%20code%20-%20Low%20density%20residential%20(LPS%20v9_2).pdf$q$, $q$'Building height' (SC1.2) - ground level to highest point of roof.$q$, $q$ldr_ao2_building_height$q$);
SELECT define_rule($q${"rule_id": "LCC.ldr_ao2_building_height", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "HEIGHT.BUILDING", "title": "Table 6.2.5.3.1 PO2/AO2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "AO2 A building on a slope of: a. less than 15 percent has a maximum building height of 8.5 metres or b. 15 percent or more has a maximum building height of 10 metres.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "ZONE", "zone": "LCC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "ldr_ao2_building_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_height\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"site slope < 15%: 8.5 m\", \"site slope >= 15%: 10 m\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): slope < 15% -> 8.5 m; slope >= 15% -> 10 m\nStructure scope 'a building' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Applicability caution: for a Dwelling house (and a class 10 building/structure for a Dwelling house) in a 'residential area' on Residential overlay map OM-10.00, Table 5.10.10.1 nominates only the 9.3.2 Dual occupancy and Dwelling house code as the requirement; the zone code is nominated only for class 10 buildings for residential activities other than a Dwelling house, and for other uses (e.g. MCU code assessment of other uses). Table 5.7.1 also nominates the zone code for building work for uses other than Dual occupancy (auxiliary unit)/Dwelling house. So this zone provision is generally NOT a requirement for a house or its Class 10a outbuildings."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.ldr_ao2_building_height@2025-07-01$q$;
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 6.2.5.3.1 AO3; Table 6.2.5.3.3$q$, 'TABLE', $q$Table 6.2.5.3.3 - Low density residential zone boundary clearance provisions | Road boundary: Acreage - 10 metres; Large suburban - 6 metres; Small acreage - 10 metres; Small lot - 4 metres; Suburban - 6 metres; Village - 6 metres. (All precincts: Dual occupancy - As per Dual occupancy and Dwelling house code.)$q$, 'VERIFIED_VERBATIM', $q$Page 5 of 6$q$, NULL, $q$6.2.5 Low density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-5%20Zone%20code%20-%20Low%20density%20residential%20(LPS%20v9_2).pdf$q$, $q$'Boundary clearance' (SC1.2) is measured 'from the part of the building or structure that is closest to the boundary, other than a part that is - a. an architectural or ornamental attachment or b. a rainwater fitting' (e.g. outside of fascia, or nearest point of roof). Note this differs from the scheme's 'Setback' definition (measured from the 'outermost projection').$q$, $q$ldr_t62533_road_boundary_clearance$q$);
SELECT define_rule($q${"rule_id": "LCC.ldr_t62533_road_boundary_clearance", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.5.3.1 AO3; Table 6.2.5.3.3", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "Table 6.2.5.3.3 - Low density residential zone boundary clearance provisions | Road boundary: Acreage - 10 metres; Large suburban - 6 metres; Small acreage - 10 metres; Small lot - 4 metres; Suburban - 6 metres; Village - 6 metres. (All precincts: Dual occupancy - As per Dual occupancy and Dwelling house code.)", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "ZONE", "zone": "LCC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "ldr_t62533_road_boundary_clearance", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_road_boundary_clearance\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"Acreage 10\", \"Large suburban 6\", \"Small acreage 10\", \"Small lot 4\", \"Suburban 6\", \"Village 6\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'All building types - 'Any other use not listed in this table' (i.e. not Dual occupancy, Relocatable home park, Residential care facility, Retirement facility)' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Cells verified against rendered page image (text extraction interleaves columns). Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Applicability caution: for a Dwelling house (and a class 10 building/structure for a Dwelling house) in a 'residential area' on Residential overlay map OM-10.00, Table 5.10.10.1 nominates only the 9.3.2 Dual occupancy and Dwelling house code as the requirement; the zone code is nominated only for class 10 buildings for residential activities other than a Dwelling house, and for other uses (e.g. MCU code assessment of other uses). Table 5.7.1 also nominates the zone code for building work for uses other than Dual occupancy (auxiliary unit)/Dwelling house. So this zone provision is generally NOT a requirement for a house or its Class 10a outbuildings."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.ldr_t62533_road_boundary_clearance@2025-07-01$q$;
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 6.2.5.3.3 (Large suburban, Small lot, Suburban, Village)$q$, 'TABLE', $q$Side boundary: Where the height of a part of the building or structure is: 4.5 metres or less - 1.5 metres; greater than 4.5 metres but not more than 7.5 metres - 2 metres; greater than 7.5 metres - 2 metres plus 0.5 metre for every 3 metres or part exceeding 7.5 metres.$q$, 'VERIFIED_VERBATIM', $q$Page 5 of 6$q$, NULL, $q$6.2.5 Low density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-5%20Zone%20code%20-%20Low%20density%20residential%20(LPS%20v9_2).pdf$q$, $q$'Side and rear boundary clearance' (SC1.2): 'the shortest distance measured horizontally from the outermost projection of the building or structure to the vertical projection of the boundary of the lot but does not include a road boundary clearance.' General 'Boundary clearance' definition (closest part, excluding architectural/ornamental attachments and rainwater fittings) also exists - manual review which governs.$q$, $q$ldr_t62533_side_clearance_height_based$q$);
SELECT define_rule($q${"rule_id": "LCC.ldr_t62533_side_clearance_height_based", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.SIDE", "title": "Table 6.2.5.3.3 (Large suburban, Small lot, Suburban, Village)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "h <= 4.5 m: 1.5 m; 4.5 < h <= 7.5 m: 2 m; h > 7.5 m: 2 + 0.5*ceil((h-7.5)/3) m, where h = height of that part of the building or structure", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/LARGE_SUBURBAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/SMALL_LOT"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/SUBURBAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_DENSITY_RESIDENTIAL/VILLAGE"}], "subjects": ["ANY"], "sources": [{"key": "ldr_t62533_side_clearance_height_based", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_boundary_clearance\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": \"h <= 4.5 m: 1.5 m; 4.5 < h <= 7.5 m: 2 m; h > 7.5 m: 2 + 0.5*ceil((h-7.5)/3) m, where h = height of that part of the building or structure\"}\nStructure scope 'All building types - any other use not listed' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Mirrors QDC MP1.2 A2 formula. Acreage and Small acreage: side 3 metres. Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Applicability caution: for a Dwelling house (and a class 10 building/structure for a Dwelling house) in a 'residential area' on Residential overlay map OM-10.00, Table 5.10.10.1 nominates only the 9.3.2 Dual occupancy and Dwelling house code as the requirement; the zone code is nominated only for class 10 buildings for residential activities other than a Dwelling house, and for other uses (e.g. MCU code assessment of other uses). Table 5.7.1 also nominates the zone code for building work for uses other than Dual occupancy (auxiliary unit)/Dwelling house. So this zone provision is generally NOT a requirement for a house or its Class 10a outbuildings."}$q$::jsonb);
