SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 6.2.5.3.3$q$, 'TABLE', $q$Rear boundary: 3 metres (Acreage, Large suburban, Small acreage, Small lot, Suburban, Village). Side boundary: 3 metres (Acreage, Small acreage).$q$, 'VERIFIED_VERBATIM', $q$Page 5 of 6$q$, NULL, $q$6.2.5 Low density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-5%20Zone%20code%20-%20Low%20density%20residential%20(LPS%20v9_2).pdf$q$, $q$'Side and rear boundary clearance' (SC1.2): 'the shortest distance measured horizontally from the outermost projection of the building or structure to the vertical projection of the boundary of the lot but does not include a road boundary clearance.' General 'Boundary clearance' definition (closest part, excluding architectural/ornamental attachments and rainwater fittings) also exists - manual review which governs.$q$, $q$ldr_t62533_rear_and_acreage_side_3m$q$);
SELECT define_rule($q${"rule_id": "LCC.ldr_t62533_rear_and_acreage_side_3m", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.REAR", "title": "Table 6.2.5.3.3", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": 3, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "ZONE", "zone": "LCC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "ldr_t62533_rear_and_acreage_side_3m", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_rear_boundary_clearance\", \"operator\": \">=\", \"value\": 3, \"unit\": \"m\", \"conditions\": [\"also min side clearance 3 m in Acreage and Small acreage precincts\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'All building types - any other use not listed' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Cells verified against rendered page image. Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Applicability caution: for a Dwelling house (and a class 10 building/structure for a Dwelling house) in a 'residential area' on Residential overlay map OM-10.00, Table 5.10.10.1 nominates only the 9.3.2 Dual occupancy and Dwelling house code as the requirement; the zone code is nominated only for class 10 buildings for residential activities other than a Dwelling house, and for other uses (e.g. MCU code assessment of other uses). Table 5.7.1 also nominates the zone code for building work for uses other than Dual occupancy (auxiliary unit)/Dwelling house. So this zone provision is generally NOT a requirement for a house or its Class 10a outbuildings."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.ldr_t62533_rear_and_acreage_side_3m@2025-07-01$q$;
