SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 6.2.7.3.1 PO4/AO4$q$, 'ACCEPTABLE_OUTCOME', $q$AO4 Development, other than an existing lawful building, provides a road boundary clearance: a. a minimum of four metres or b. where the building or structure aligns with the building setback of one or more adjoining buildings.$q$, 'VERIFIED_VERBATIM', $q$Page 2 of 4$q$, NULL, $q$6.2.7 Low-medium density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-7%20Zone%20code%20-%20Low-medium%20density%20residential%20(LPS%20v9_2).pdf$q$, $q$'Boundary clearance' (SC1.2) is measured 'from the part of the building or structure that is closest to the boundary, other than a part that is - a. an architectural or ornamental attachment or b. a rainwater fitting' (e.g. outside of fascia, or nearest point of roof). Note this differs from the scheme's 'Setback' definition (measured from the 'outermost projection').$q$, $q$lmdr_ao4_road_clearance$q$);
SELECT define_rule($q${"rule_id": "LCC.lmdr_ao4_road_clearance", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.FRONTAGE", "title": "Table 6.2.7.3.1 PO4/AO4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "AO4 Development, other than an existing lawful building, provides a road boundary clearance: a. a minimum of four metres or b. where the building or structure aligns with the building setback of one or more adjoining buildings.", "extracted_value": 4, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "ZONE", "zone": "LCC:LOW_MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "lmdr_ao4_road_clearance", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_road_boundary_clearance\", \"operator\": \"conditional\", \"value\": 4, \"unit\": \"m\", \"conditions\": [\"or align with building setback of one or more adjoining buildings\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Development, other than an existing lawful building' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Applicability caution: for a Dwelling house (and a class 10 building/structure for a Dwelling house) in a 'residential area' on Residential overlay map OM-10.00, Table 5.10.10.1 nominates only the 9.3.2 Dual occupancy and Dwelling house code as the requirement; the zone code is nominated only for class 10 buildings for residential activities other than a Dwelling house, and for other uses (e.g. MCU code assessment of other uses). Table 5.7.1 also nominates the zone code for building work for uses other than Dual occupancy (auxiliary unit)/Dwelling house. So this zone provision is generally NOT a requirement for a house or its Class 10a outbuildings. For Dwelling houses, 9.3.2 AO4(b) sets 4 m (alternative provision)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.lmdr_ao4_road_clearance@2025-07-01$q$;
SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 6.2.7.3.1 PO6/AO6$q$, 'ACCEPTABLE_OUTCOME', $q$AO6 A building, other than an existing lawful building, in the Townhouse precinct has: a. minimum side boundary clearances: i. where the height of part of the building or structure is: A. 4.5 metres or less - 1.5 metres B. greater than 4.5 metres but not more than 7.5 metres - 2 metres C. greater than 7.5 metres - 2 metres plus 0.5 metres for every 3 metres or part exceeding 7.5 metres b. a minimum rear boundary clearance of three metres.$q$, 'VERIFIED_VERBATIM', $q$Page 2 of 4$q$, NULL, $q$6.2.7 Low-medium density residential zone code$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%206-2-7%20Zone%20code%20-%20Low-medium%20density%20residential%20(LPS%20v9_2).pdf$q$, $q$'Side and rear boundary clearance' (SC1.2): 'the shortest distance measured horizontally from the outermost projection of the building or structure to the vertical projection of the boundary of the lot but does not include a road boundary clearance.' General 'Boundary clearance' definition (closest part, excluding architectural/ornamental attachments and rainwater fittings) also exists - manual review which governs.$q$, $q$lmdr_ao6_townhouse_side_rear$q$);
SELECT define_rule($q${"rule_id": "LCC.lmdr_ao6_townhouse_side_rear", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "SETBACK.SIDE", "title": "Table 6.2.7.3.1 PO6/AO6", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": {"op": "unencoded", "text": "h <= 4.5: 1.5 m; 4.5 < h <= 7.5: 2 m; h > 7.5: 2 + 0.5 per 3 m or part over 7.5 m; rear >= 3 m", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "PRECINCT", "precinct": "LCC:LOW_MEDIUM_DENSITY_RESIDENTIAL/TOWNHOUSE"}], "subjects": ["ANY"], "sources": [{"key": "lmdr_ao6_townhouse_side_rear", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_side_boundary_clearance\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": \"h <= 4.5: 1.5 m; 4.5 < h <= 7.5: 2 m; h > 7.5: 2 + 0.5 per 3 m or part over 7.5 m; rear >= 3 m\"}\nStructure scope 'A building, other than an existing lawful building' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not listed in Part 1 Table 1.6.1 (which lists only Dual occupancy and Dwelling house code PO3/AO3, PO4/AO4, PO5/AO5, PO6/AO6, PO7/AO7(.1), PO8/AO8, PO9/AO9, PO12/AO12 as QDC alternative provisions). Ordinary planning assessment benchmark only. Applicability caution: for a Dwelling house (and a class 10 building/structure for a Dwelling house) in a 'residential area' on Residential overlay map OM-10.00, Table 5.10.10.1 nominates only the 9.3.2 Dual occupancy and Dwelling house code as the requirement; the zone code is nominated only for class 10 buildings for residential activities other than a Dwelling house, and for other uses (e.g. MCU code assessment of other uses). Table 5.7.1 also nominates the zone code for building work for uses other than Dual occupancy (auxiliary unit)/Dwelling house. So this zone provision is generally NOT a requirement for a house or its Class 10a outbuildings."}$q$::jsonb);
