SELECT define_provision($q$LCC_PLANNING_SCHEME_2015@2025-07-01$q$, $q$Table 8.2.7.3.1 AO3.1; SC6.2.4 PSP4 part 4$q$, 'ACCEPTABLE_OUTCOME', $q$AO3.1 Development being one or more of the following, complies with part 4 of Planning scheme policy 4 - Heritage: a. the raising of a house or building underneath or b. the addition of an extension or c. the building of a class 10a building/structure being a carport or garage or d. the building of a class 10b building/structure being a deck, veranda or swimming pool. || PSP4: 'A class 10a building, being a carport or garage, is designed and constructed to complement the original house design and not detract from the character and presence of the house in the street, by: i. ensuring the carport or garage does not dominate the street frontage or ii. locating the carport or garage at the rear of the site, where it does not block views of the house.' ... 'A class 10b building/structure, being a swimming pool, is designed and constructed to complement and preserve the character and presence of a heritage premises by locating the swimming pool at the side or rear, rather than in front of the house.'$q$, 'VERIFIED_VERBATIM', $q$8.2.7 page 1; PSP4 pages 14-15$q$, NULL, $q$8.2.7 Heritage overlay code + Planning scheme policy 4 - Heritage part 4$q$, NULL, $q$https://lcc-docs-planning.s3-ap-southeast-2.amazonaws.com/root/Logan%20Planning%20Scheme%202015/LPS%202015%20V9.2%20(July%202025)/Documents%20(LPS%20V9.2)/Part%208-2-7%20Overlay%20-%20Heritage%20(LPS%20v9_2).pdf$q$, NULL, $q$heritage_ao3_1_class10_pool_siting$q$);
SELECT define_rule($q${"rule_id": "LCC.heritage_ao3_1_class10_pool_siting", "instrument_version": "LCC_PLANNING_SCHEME_2015@2025-07-01", "topic": "POOL.SETBACK", "title": "Table 8.2.7.3.1 AO3.1; SC6.2.4 PSP4 part 4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTABLE_OUTCOME", "measurement": "SCHEME_POOL_SETBACK", "operator": ">=", "value": {"op": "unencoded", "text": "AO3.1 Development being one or more of the following, complies with part 4 of Planning scheme policy 4 - Heritage: a. the raising of a house or building underneath or b. the addition of an extension or c. the building of a class 10a building/structure being a carport or garage or d. the building of a class 10b building/structure being a deck, veranda or swimming pool. || PSP4: 'A class 10a building, being a carport or garage, is designed and constructed to complement the original house design and not detract from the character and presence of the house in the street, by: i. ensuring the carport or garage does not dominate the street frontage or ii. locating the carport or garage at the rear of the site, where it does not block views of the house.' ... 'A class 10b building/structure, being a swimming pool, is designed and constructed to complement and preserve the character and presence of a heritage premises by locating the swimming pool at the side or rear, rather than in front of the house.'", "extracted_value": null, "extracted_operator": "conditional"}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2025-07-01", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "LOGAN"}, {"level": "OVERLAY", "overlay": "LCC:OV:HERITAGE_OVERLAY_LOCAL_HERITAGE_AREA_OM_07_01"}], "subjects": ["POOL", "CLASS_10A", "CLASS_1", "OUTDOOR_STRUCTURE"], "sources": [{"key": "heritage_ao3_1_class10_pool_siting", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"siting_relative_to_heritage_house\", \"operator\": \"conditional\", \"value\": null, \"unit\": null, \"conditions\": [\"pool/deck/veranda at side or rear, not in front of house\", \"carport/garage not dominating frontage or at rear\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'class 10a carport/garage; class 10b deck, veranda, swimming pool (as described by the code)' mapped by keyword to ['POOL', 'CLASS_10A', 'CLASS_1', 'OUTDOOR_STRUCTURE']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Building work in a heritage area is code assessable (Table 5.10.7.1) unless by/on land of local government; council is assessment manager. Qualitative only - no numeric setbacks. Only scheme provision found that addresses swimming pool siting."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$LCC.heritage_ao3_1_class10_pool_siting@2025-07-01$q$;

INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$QHC transition: v9.2 9.3.2 AO1 and Table 1.6.1 refer to 'QDC MP 1.1/1.2' and 'the QDC'. Need legal confirmation that Table 1.6.1 alternative provisions continue to operate as alternatives to QHC Parts 1.1/1.2 from 1 Sept 2026 and how AO1's references are read. No Logan amendment referencing the QHC was found (S3 bucket shows no post-2025 scheme files; council page still lists V9.2).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$Urban LDR (Small lot, Suburban, Large suburban, Village), LMDR and MDR lots: 9.3.2 sets no house road/side/rear clearance (except carport AO4(a) and LMDR 4 m road), so QDC/QHC applies. Confirm the zone code Tables 6.2.5.3.3 / 6.2.7 / local plan clearances never apply to a Dwelling house or its Class 10a under Table 5.10.10.1 (my reading: they do not).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$Large outbuildings (>150 m2) on urban LDR/LMDR/MDR lots: AO7.1(b)(i) requires Table 9.3.2.3.2 clearances, but that table lists only EC, LDR Acreage/Small acreage, RR (6 m) and EMC/Rural (20 m). For other zones, is AO7.1(b)(i) automatically satisfied, or is a >150 m2 outbuilding unable to comply (making it code assessable)? Needs council/certifier confirmation.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$Whether AO7.1's 150/300 m2 cumulative total includes carports and attached garages (text: 'being sheds or detached garages').$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$Whether AO7.1(b)(ii) 5.5 m height (large outbuildings) is part of the s33 alternative provision or only a planning requirement.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$Residential overlay map OM-10.00 extent not checked spatially; the 'Residential area' definition lists zones, but the map is the trigger.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$TLPI No. 1/2024 commenced 6 March 2025; check whether it has expired/been replaced (TLPIs have a limited life) and whether flood provisions in 9.3.2 changed.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$EC zone impact trigger refers to 'the building height in the Dual occupancy and Dwelling house code', but 9.3.2 v9.2 has no general dwelling height AO - drafting inconsistency to confirm.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$No pool setback, pool equipment, built-to-boundary wall length, impervious area or landscaping provisions for dwelling houses were found in 9.3.2 or the residential zone codes (pool siting addressed only qualitatively in the Heritage overlay/PSP4). Built-to-boundary walls therefore follow QDC/QHC.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$LOGAN$q$, $q$LCC_PLANNING_SCHEME_2015$q$, 'MEDIUM', $q$Council 'Domestic outbuildings (garages and sheds)' web page returned 404/403 to automated fetch; only a search-engine snippet was seen.$q$);
